-- FAQ de Teclab, tanda 2 (28/11/2026): Seguros (228) de 5 a 9; Marketing Digital (223), (con la respuesta de la matrícula
-- completada con los requisitos administrativos de la SSN, a pedido de revision_final)
-- Gestión Agraria (229) y Quality Assurance (219) de 3 a 9. Textos aprobados por el usuario.
-- Fuentes: fichas oficiales de teclab.edu.ar, plan en D1, certificados en conocimiento/teclab.md,
-- carreras/teclab/articulaciones-teclab.json; nombres de Siglo 21 verificados en
-- 21.edu.ar/carreras-y-programas. Títulos como en D1 (carreras.titulo); conocimiento/teclab.md
-- dice «Técnico Superior en Calidad del Software (Quality Assurance)»: confirmar contra la resolución.
-- Cada UPDATE exige el JSON actual: si cambió, no escribe.
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué hace un QA tester?","respuesta":"Prueba aplicaciones para detectar fallas, registra los problemas encontrados y verifica las correcciones. También diseña casos de prueba y colabora con el equipo de desarrollo para revisar la calidad del software."},{"pregunta":"¿Qué se aprende en la Tecnicatura en Quality Assurance?","respuesta":"Estudiás lógica de programación, bases de datos, scripting, desarrollo de tests, planificación de pruebas y testing de aplicaciones móviles. Estos contenidos permiten organizar pruebas y avanzar en su automatización."},{"pregunta":"¿Cuál es la diferencia entre Quality Assurance y Programación?","respuesta":"Programación se orienta a construir aplicaciones y sus funcionalidades. Quality Assurance se enfoca en comprobar su funcionamiento y detectar errores. Ambos perfiles trabajan con software; QA también utiliza programación para automatizar pruebas."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y prácticas aplicadas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Quality Assurance, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente de Pruebas de Calidad."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con Lógica de programación, Base de datos y Scripting en el primer cuatrimestre."},{"pregunta":"¿Tiene salida laboral?","respuesta":"Sí. Podés trabajar como QA tester, analista QA o QA engineer, en testing y control de calidad de software."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con Ingeniería en Software y con la Licenciatura en Seguridad Informática y Ciberseguridad de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 219 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué hace un QA tester?","respuesta":"Prueba aplicaciones para detectar fallas, registra los problemas encontrados y verifica las correcciones. También diseña casos de prueba y colabora con el equipo de desarrollo para revisar la calidad del software."},{"pregunta":"¿Qué se aprende en la Tecnicatura en Quality Assurance?","respuesta":"Estudiás lógica de programación, bases de datos, scripting, desarrollo de tests, planificación de pruebas y testing de aplicaciones móviles. Estos contenidos permiten organizar pruebas y avanzar en su automatización."},{"pregunta":"¿Cuál es la diferencia entre Quality Assurance y Programación?","respuesta":"Programación se orienta a construir aplicaciones y sus funcionalidades. Quality Assurance se enfoca en comprobar su funcionamiento y detectar errores. Ambos perfiles trabajan con software; QA también utiliza programación para automatizar pruebas."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Marketing Digital?","respuesta":"Estudiás estrategias de marketing, gestión de marca, publicidad digital, contenidos y comercio electrónico. La formación incluye presupuestos y análisis de resultados para planificar y mejorar acciones comerciales en canales digitales."},{"pregunta":"¿Marketing Digital es solamente manejar redes sociales?","respuesta":"No. Las redes sociales son uno de sus canales. La carrera también aborda publicidad digital, gestión de marca, contenidos, comercio electrónico y métricas para integrar distintas acciones dentro de una estrategia."},{"pregunta":"¿Qué tareas puede realizar un técnico en Marketing Digital?","respuesta":"Puede planificar campañas y contenidos, administrar publicidad digital y analizar indicadores para evaluar resultados. También puede colaborar en estrategias de marca y acciones comerciales para negocios que venden o se comunican por canales digitales."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y actividades prácticas, así que podés combinarla con el trabajo."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Marketing Digital, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente en Marketing Digital."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con estrategias de marketing digital, gestión de publicidad digital y gestión de marca en el primer cuatrimestre."},{"pregunta":"¿Tiene salida laboral?","respuesta":"Sí. Podés trabajar en publicidad digital y redes sociales, en agencias, en áreas de marketing de empresas o en proyectos propios y de forma independiente."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Publicidad y con la Licenciatura en Marketing y Comercialización de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 223 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Marketing Digital?","respuesta":"Estudiás estrategias de marketing, gestión de marca, publicidad digital, contenidos y comercio electrónico. La formación incluye presupuestos y análisis de resultados para planificar y mejorar acciones comerciales en canales digitales."},{"pregunta":"¿Marketing Digital es solamente manejar redes sociales?","respuesta":"No. Las redes sociales son uno de sus canales. La carrera también aborda publicidad digital, gestión de marca, contenidos, comercio electrónico y métricas para integrar distintas acciones dentro de una estrategia."},{"pregunta":"¿Qué tareas puede realizar un técnico en Marketing Digital?","respuesta":"Puede planificar campañas y contenidos, administrar publicidad digital y analizar indicadores para evaluar resultados. También puede colaborar en estrategias de marca y acciones comerciales para negocios que venden o se comunican por canales digitales."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Seguros?","respuesta":"Aprendés a analizar riesgos, elegir coberturas y gestionar pólizas y siniestros, con conocimientos técnicos y legales y herramientas digitales para el negocio asegurador."},{"pregunta":"¿Puedo obtener la matrícula de Productor Asesor de Seguros con este título?","respuesta":"El título permite obtener la matrícula de Productor Asesor de Seguros sin rendir el examen de competencia, cumpliendo los requisitos administrativos vigentes ante la SSN."},{"pregunta":"¿Cuál es la salida laboral de la Tecnicatura en Seguros?","respuesta":"Podés trabajar en aseguradoras, brokers, oficinas de productores y áreas de gestión de siniestros. Para ejercer como Productor Asesor de Seguros tenés que completar la matriculación ante la SSN."},{"pregunta":"¿Cuánto dura la Tecnicatura en Seguros?","respuesta":"Dura 2 años y se cursa 100% online. Te recibís de Técnico Superior en Seguros y en el camino obtenés el certificado intermedio de Auxiliar de Seguros."},{"pregunta":"¿Qué hace un técnico superior en seguros?","respuesta":"Evalúa riesgos y orienta la elección de coberturas, prepara cotizaciones, gestiona pólizas y acompaña la denuncia y el seguimiento de siniestros. Trabaja en aseguradoras, brokers, oficinas de productores o con su propia cartera de clientes como productor asesor de seguros."},{"pregunta":"¿Qué es un Productor Asesor de Seguros?","respuesta":"Es el profesional matriculado ante la Superintendencia de Seguros de la Nación (SSN) que está habilitado para asesorar y comercializar seguros a personas y empresas."},{"pregunta":"¿Cómo son las clases?","respuesta":"Son online y en vivo, y quedan grabadas para que las veas cuando te quede cómodo. Se complementan con actividades prácticas."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con Marco legal del contrato de seguros y Contrato de seguros en el primer cuatrimestre, y avanza paso a paso en el mercado asegurador."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés la Práctica profesional, donde aplicás lo aprendido a situaciones de trabajo."}]}]' WHERE id = 228 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Seguros?","respuesta":"Aprendés a analizar riesgos, elegir coberturas y gestionar pólizas y siniestros, con conocimientos técnicos y legales y herramientas digitales para el negocio asegurador."},{"pregunta":"¿Puedo obtener la matrícula de Productor Asesor de Seguros con este título?","respuesta":"El título permite obtener la matrícula de Productor Asesor de Seguros sin rendir el examen de competencia."},{"pregunta":"¿Cuál es la salida laboral de la Tecnicatura en Seguros?","respuesta":"Podés trabajar en aseguradoras, brokers, oficinas de productores y áreas de gestión de siniestros. Para ejercer como Productor Asesor de Seguros tenés que completar la matriculación ante la SSN."},{"pregunta":"¿Cuánto dura la Tecnicatura en Seguros?","respuesta":"Dura 2 años y se cursa 100% online. Te recibís de Técnico Superior en Seguros y en el camino obtenés el certificado intermedio de Auxiliar de Seguros."},{"pregunta":"¿Qué hace un técnico superior en seguros?","respuesta":"Evalúa riesgos y orienta la elección de coberturas, prepara cotizaciones, gestiona pólizas y acompaña la denuncia y el seguimiento de siniestros. Trabaja en aseguradoras, brokers, oficinas de productores o con su propia cartera de clientes como productor asesor de seguros."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión Agraria?","respuesta":"Estudiás administración de la empresa agraria, presupuestos, circuitos contables, cultivos y producción animal. La formación combina gestión y conocimientos del sector agropecuario para organizar recursos y procesos."},{"pregunta":"¿Qué hace un técnico en Gestión Agraria?","respuesta":"Participa en la administración de recursos, costos y presupuestos de una empresa agropecuaria. También puede colaborar en la planificación y el seguimiento de la producción y en el análisis de la comercialización."},{"pregunta":"¿Cuál es la salida laboral de Gestión Agraria?","respuesta":"La formación se vincula con tareas administrativas, comerciales y de seguimiento de procesos en empresas y establecimientos agropecuarios. Permite participar en la organización de recursos y unidades de negocio del sector."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y actividades prácticas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Gestión de la Empresa Agraria, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Auxiliar en Gestión de la Empresa Agraria."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con la gestión operativa de la empresa agraria y los circuitos administrativos contables en el primer cuatrimestre."},{"pregunta":"¿Puedo trabajar en el sector antes de terminar?","respuesta":"Sí. A medida que avanzás podés postularte a puestos iniciales de administración, control de gestión o apoyo en proyectos productivos; depende de lo que pida cada empresa."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Administración Agraria de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 229 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión Agraria?","respuesta":"Estudiás administración de la empresa agraria, presupuestos, circuitos contables, cultivos y producción animal. La formación combina gestión y conocimientos del sector agropecuario para organizar recursos y procesos."},{"pregunta":"¿Qué hace un técnico en Gestión Agraria?","respuesta":"Participa en la administración de recursos, costos y presupuestos de una empresa agropecuaria. También puede colaborar en la planificación y el seguimiento de la producción y en el análisis de la comercialización."},{"pregunta":"¿Cuál es la salida laboral de Gestión Agraria?","respuesta":"La formación se vincula con tareas administrativas, comerciales y de seguimiento de procesos en empresas y establecimientos agropecuarios. Permite participar en la organización de recursos y unidades de negocio del sector."}]}]';
